@namespace sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <ReferenceForm Index="index"
                       Name="@reference.Name"
                       Relationship="@reference.Relationship"
                       Email="@reference.Email"
                       Phone="@reference.Phone"
                       CanRemove="@(References.Count > 2)"
                       NameChanged="e => UpdateReference(index, reference with { Name = e })"
                       RelationshipChanged="e => UpdateReference(index, reference with { Relationship = e })"
                       EmailChanged="e => UpdateReference(index, reference with { Email = e })"
                       PhoneChanged="e => UpdateReference(index, reference with { Phone = e })"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBackClicked">Back</button>
        <button class="btn btn-primary" @onclick="OnNextClicked">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnBackClicked { get; set; }
    [Parameter] public EventCallback OnNextClicked { get; set; }

    private async Task UpdateReference(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        await ReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            var list = new List<ReferenceModel>(References) { new() };
            await ReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            var list = new List<ReferenceModel>(References);
            list.RemoveAt(index);
            await ReferencesChanged.InvokeAsync(list);
        }
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}

@namespace sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below:</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxCharacters"
                  value="@CoverLetter"
                  @oninput="e => CoverLetterChanged.InvokeAsync(e.Value?.ToString() ?? "")"></textarea>
        <div class="character-count @(CoverLetter.Length > MaxCharacters ? "over-limit" : "")">
            @CoverLetter.Length / @MaxCharacters characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBackClicked">Back</button>
        <button class="btn btn-primary" @onclick="OnNextClicked">Next</button>
    </div>
</div>

@code {
    private const int MaxCharacters = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBackClicked { get; set; }
    [Parameter] public EventCallback OnNextClicked { get; set; }
}

@namespace sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply
@using static sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply.WorkHistoryStep
@using static sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply.ReferencesStep

<div class="step-content">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-data">
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    @reference.Email | @reference.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(SubmissionError))
        {
            <div class="validation-error">@SubmissionError</div>
        }

        <div class="step-buttons">
