namespace sv_d7276b6849d341f59d9d0ceafe01a4a1.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@namespace sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply
@using sv_d7276b6849d341f59d9d0ceafe01a4a1.Models
@using static sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply.WorkHistoryStep
@using static sv_d7276b6849d341f59d9d0ceafe01a4a1.Components.Pages.Apply.ReferencesStep
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              FullNameChanged="e => fullName = e"
                              EmailChanged="e => email = e"
                              PhoneChanged="e => phone = e"
                              AddressChanged="e => address = e"
                              ValidationError="@validationError"
                              IsValidating="@isValidating"
                              OnNextClicked="ValidateAndAdvancePersonalInfo" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             EntriesChanged="e => workEntries = e"
                             ValidationError="@validationError"
                             OnBackClicked="GoBack"
                             OnNextClicked="ValidateAndAdvanceWorkHistory" />
            break;
        case 2:
            <ReferencesStep References="references"
                            ReferencesChanged="e => references = e"
                            ValidationError="@validationError"
                            OnBackClicked="GoBack"
                            OnNextClicked="ValidateAndAdvanceReferences" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="e => coverLetter = e"
                             ValidationError="@validationError"
                             OnBackClicked="GoBack"
                             OnNextClicked="ValidateAndAdvanceCoverLetter" />
            break;
        case 4:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting" IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId" SubmissionError="@submissionError"
                        OnEditSection="NavigateToStep"
                        OnBackClicked="GoBack"
                        OnSubmitClicked="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string? validationError;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submissionError;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        validationError = null;
        currentStep = step;
    }

    private void GoBack()
    {
        validationError = null;
        currentStep--;
    }

    private async Task ValidateAndAdvancePersonalInfo()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!emailValid)
            {
                validationError = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        currentStep++;
    }

    private void ValidateAndAdvanceWorkHistory()
    {
        validationError = null;

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Company name and job title are required for all positions.";
                return;
            }
        }

        currentStep++;
    }

    private void ValidateAndAdvanceReferences()
    {
        validationError = null;

        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                validationError = "All fields are required for each reference.";
                return;
            }
        }

        currentStep++;
    }

    private void ValidateAndAdvanceCoverLetter()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationError = "A cover letter is required.";
            return;
        }

        if (coverLetter.Length > 2000)
        {
            validationError = "Cover letter must not exceed 2000 characters.";
            return;
        }

        currentStep++;
    }

    private async Task SubmitApplication()
    {
        submissionError = null;
        isSubmitting = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submissionError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-page h1 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #d1d5db;
    background: #fff;
    color: #6b7280;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-check {
    font-size: 1rem;
}

.step-label {
    font-size: 0.75rem;
    color: #6b7280;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    list-style: none;
}

.step-connector.completed {
    background: #16a34a;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 0.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #6b7280;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #374151;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.form-check input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn {
    padding: 0.625rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #2563eb;
    color: #fff;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-outline {
    background: transparent;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-outline:hover {
    background: #f9fafb;
}

.btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

.btn-danger {
    background: #ef4444;
    color: #fff;
}

.btn-danger:hover {
    background: #dc2626;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-error {
    color: #dc2626;
    background: #fef2f2;
    border: 1px solid #fecaca;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

/* Work Entry / Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f9fafb;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #374151;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.character-count {
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.character-count.over-limit {
    color: #dc2626;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #6b7280;
}

.review-data dd {
    margin: 0;
    color: #1f2937;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.875rem;
    color: #6b7280;
}

.review-description {
    margin-top: 0.5rem;
    color: #4b5563;
    font-size: 0.9rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #374151;
    line-height: 1.6;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
}

.submission-confirmation h3 {
    color: #16a34a;
    margin-top: 0;
}

