        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Company"
               @oninput="OnCompanyInput" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Title"
               @oninput="OnTitleInput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDateFormatted"
                   @onchange="OnStartDateChange" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDateFormatted"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChange" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" id="@CheckboxId" checked="@IsCurrent"
               @onchange="OnIsCurrentChange" />
        <label for="@CheckboxId">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @oninput="OnDescriptionInput"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private string StartDateFormatted => StartDate.ToString("yyyy-MM-dd");
    private string? EndDateFormatted => EndDate?.ToString("yyyy-MM-dd");
    private string CheckboxId => $"current-{Index}";

    private Task OnCompanyInput(ChangeEventArgs e) => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    private Task OnTitleInput(ChangeEventArgs e) => TitleChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    private Task OnDescriptionInput(ChangeEventArgs e) => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);

    private Task OnStartDateChange(ChangeEventArgs e)
    {
        var value = e.Value?.ToString();
        var date = string.IsNullOrEmpty(value) ? DateTime.Today : DateTime.Parse(value);
        return StartDateChanged.InvokeAsync(date);
    }

    private Task OnEndDateChange(ChangeEventArgs e)
    {
        var value = e.Value?.ToString();
        DateTime? date = string.IsNullOrEmpty(value) ? null : DateTime.Parse(value);
        return EndDateChanged.InvokeAsync(date);
    }

    private Task OnIsCurrentChange(ChangeEventArgs e)
    {
        var isChecked = (bool)(e.Value ?? false);
        return IsCurrentChanged.InvokeAsync(isChecked);
    }
}

